<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { RefreshRight, Search } from '@element-plus/icons-vue';
import { apiRequest } from '../api/request';
interface Order{id:string;orderNo:string;orderType:string;tenant:{name:string};targetPlan?:{name:string};addon?:{name:string};addonQuantity:number;amountCents:number;paymentAmountCents?:number;paymentMethod?:string;status:string;requestedByName:string;requestedAt:string;activatedAt?:string}
const items=ref<Order[]>([]),total=ref(0),loading=ref(false);const query=reactive({status:'',orderType:'',keyword:'',page:1,pageSize:20});
const typeName:Record<string,string>={UPGRADE:'套餐升级',RENEW:'续费',EXPANSION:'扩容'},statusName:Record<string,string>={PENDING_PAYMENT:'待支付',PENDING_REVIEW:'待审核',APPROVED:'已完成',REJECTED:'已驳回',PAYMENT_CLOSED:'支付已关闭',PAYMENT_FAILED:'支付失败'};
const statusType=(v:string)=>v==='APPROVED'?'success':['REJECTED','PAYMENT_FAILED'].includes(v)?'danger':v==='PAYMENT_CLOSED'?'info':'warning';const money=(v:number)=>`¥${(v/100).toLocaleString('zh-CN',{minimumFractionDigits:2})}`;const time=(v?:string)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'-';
async function load(){loading.value=true;try{const result=await apiRequest<{items:Order[];total:number}>({url:'/api/subscriptions/upgrade-requests',method:'GET',params:{...query,status:query.status||undefined,orderType:query.orderType||undefined,keyword:query.keyword.trim()||undefined}});items.value=result.items;total.value=result.total}finally{loading.value=false}}onMounted(load);
</script>
<template><div><div class="page-actions"><div><h1 class="page-title">订单管理</h1><p class="page-description">集中查询客户套餐升级、续费和扩容订单及处理结果</p></div><el-button :icon="RefreshRight" @click="load">刷新</el-button></div><section class="table-panel"><div class="toolbar"><el-input v-model="query.keyword" clearable :prefix-icon="Search" placeholder="搜索订单号、租户或申请人" @keyup.enter="query.page=1;load()"/><el-select v-model="query.orderType" clearable placeholder="全部类型" @change="query.page=1;load()"><el-option label="套餐升级" value="UPGRADE"/><el-option label="续费" value="RENEW"/><el-option label="扩容" value="EXPANSION"/></el-select><el-select v-model="query.status" clearable placeholder="全部状态" @change="query.page=1;load()"><el-option label="待支付" value="PENDING_PAYMENT"/><el-option label="待审核" value="PENDING_REVIEW"/><el-option label="已完成" value="APPROVED"/><el-option label="已驳回" value="REJECTED"/><el-option label="支付已关闭" value="PAYMENT_CLOSED"/><el-option label="支付失败" value="PAYMENT_FAILED"/></el-select><el-button @click="query.page=1;load()">查询</el-button></div><el-table v-loading="loading" :data="items" empty-text="暂无订单"><el-table-column prop="orderNo" label="订单号" min-width="200"/><el-table-column label="租户 / 申请人" min-width="180"><template #default="{row}"><div class="stack"><b>{{row.tenant.name}}</b><span>{{row.requestedByName}}</span></div></template></el-table-column><el-table-column label="类型" width="110"><template #default="{row}">{{typeName[row.orderType]}}</template></el-table-column><el-table-column label="内容" min-width="170"><template #default="{row}">{{row.targetPlan?.name||row.addon?.name}}<span v-if="row.addon"> × {{row.addonQuantity}}</span></template></el-table-column><el-table-column label="金额" width="150"><template #default="{row}"><div><b>{{money(row.amountCents)}}</b></div><small v-if="row.paymentMethod==='ALIPAY'&&row.paymentAmountCents!==row.amountCents" class="sandbox">沙箱实付 {{money(row.paymentAmountCents||1)}}</small></template></el-table-column><el-table-column label="支付方式" width="120"><template #default="{row}">{{row.paymentMethod==='ALIPAY'?'支付宝':'线下凭证'}}</template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="statusType(row.status)">{{statusName[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column label="提交时间" min-width="175"><template #default="{row}">{{time(row.requestedAt)}}</template></el-table-column><el-table-column label="权益生效时间" min-width="175"><template #default="{row}">{{time(row.activatedAt)}}</template></el-table-column></el-table><div class="pager"><el-pagination v-model:current-page="query.page" layout="total, prev, pager, next" :total="total" @current-change="load"/></div></section></div></template>
<style scoped>.toolbar{display:grid;grid-template-columns:minmax(260px,1fr) 150px 150px auto;gap:12px;margin-bottom:18px}.stack{display:grid;gap:4px}.stack span{color:#8492a6;font-size:12px}.sandbox{color:#d97706}.pager{display:flex;justify-content:flex-end;margin-top:18px}@media(max-width:800px){.toolbar{grid-template-columns:1fr 1fr}.toolbar>:first-child{grid-column:1/-1}}</style>
